scwin.checkVal1 = function() {
	return onviewchange == 1;
}
scwin.checkVal2 = function() {
	return changed == 1;
}
scwin.checkVal3 = function() {
	return onviewchange == 2;
}
scwin.checkVal4 = function() {
	return changed == 2;
}
scwin.checkVal5 = function() {
	return WebSquare.wUnit.getObjById('autoComplete2').getText() == '경기도1';
}

scwin.checkVal6 = function() {
	return onviewchange == 3;
}
scwin.checkVal7 = function() {
	return changed == 3;
}
scwin.checkVal8 = function() {
	return onviewchange == 4;
}
scwin.checkVal9 = function() {
	return changed == 4;
}
scwin.checkVal10 = function() {
	return WebSquare.wUnit.getObjById('autoComplete4').getText() != null;
}
scwin.checkVal11 = function() {
	return WebSquare.wUnit.getObjById('autoComplete4').getText() == '경기도1';
}
scwin.checkVal12 = function() {
	return onviewchange == 5;
}
scwin.checkVal13 = function() {
	return changed == 5;
}

scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 
    //1.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2_label').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2_input').focus()");
    WebSquare.wUnit.addCommand("pause", "2000");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 1. 
    //2. 
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('autoComplete2').getText() == null", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step
    //
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2_label').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2_input').focus()");
    WebSquare.wUnit.addCommand("pause", "2000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#autoComplete2_input').val('')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate4()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step
    //
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal5()", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Test step
    //
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2_label').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete2_input').focus()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#autoComplete2_input').val('')");
    WebSquare.wUnit.addCommand("pause", "1000");
    //서울
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate5()");
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate6()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step
    //
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal6()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal7()", "true");
    // Test step 1. 
    //1.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete4_label').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete4_input').focus()");
    WebSquare.wUnit.addCommand("pause", "2000");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate7()");
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate8()");
    WebSquare.wUnit.addCommand("pause", "500");	

    // verify step 1. 
    //2. 
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal8()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal9()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal10()", "true");
    WebSquare.wUnit.addCommand("pause", "2000");
    //Test step
    //
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete4_label').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete4_label').focus()");
    WebSquare.wUnit.addCommand("pause", "2000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#autoComplete4_input').val('')");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate7()");
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate8()");
    WebSquare.wUnit.addCommand("pause", "500");	

	//WebSquare.wUnit.addCommand("set", $p.id+"autoComplete4_itemTable_0.click()");

    //Verify step
    //
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal8()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal9()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal11()", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Test step
    //
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete4_label').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete4_input').focus()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#autoComplete4_input').val('')");
    WebSquare.wUnit.addCommand("pause", "1000");
    //서울
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate9()");
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate10()");
    WebSquare.wUnit.addCommand("pause", "500");		
    //Verify step
    //
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal12()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal13()", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

